33	/**
34	 * Builder for {@link SessionStoreWithHeaders} instances.
35	 *
36	 * This is analogous to {@link SessionStoreBuilder}, but uses
37	 * {@link AggregationWithHeaders} as the value wrapper and wires up the
38	 * header-aware store stack (change-logging, caching, metering).
39	 */
40	public class SessionStoreBuilderWithHeaders<K, V>
41	    extends AbstractStoreBuilder<K, AggregationWithHeaders<V>, SessionStoreWithHeaders<K, V>> {
42	
43	    private final SessionBytesStoreSupplier storeSupplier;
44	
45	    public SessionStoreBuilderWithHeaders(final SessionBytesStoreSupplier storeSupplier,
46	                                          final Serde<K> keySerde,
47	                                          final Serde<V> valueSerde,
48	                                          final Time time) {
49	        super(
50	            Objects.requireNonNull(storeSupplier, "storeSupplier cannot be null").name(),
51	            keySerde,
52	            valueSerde == null ? null : new AggregationWithHeadersSerde<>(valueSerde),
53	            time
54	        );
55	        Objects.requireNonNull(storeSupplier.metricsScope(), "storeSupplier's metricsScope can't be null");
56	        this.storeSupplier = storeSupplier;
57	    }
58	
59	    @Override
60	    public SessionStoreWithHeaders<K, V> build() {
61	        SessionStore<Bytes, byte[]> sessionStore = storeSupplier.get();
62	
63	        if (!(sessionStore instanceof HeadersBytesStore)) {
64	            if (sessionStore.persistent()) {
65	                sessionStore = new SessionToHeadersStoreAdapter(sessionStore);
66	            } else {
67	                sessionStore = new InMemorySessionStoreWithHeadersMarker(sessionStore);
68	            }
69	        }
70	        return new MeteredSessionStoreWithHeaders<>(
71	            maybeWrapCaching(maybeWrapLogging(sessionStore)),
72	            storeSupplier.metricsScope(),
73	            keySerde,
74	            valueSerde,
75	            time
76	        );
77	    }
78	
79	    private SessionStore<Bytes, byte[]> maybeWrapCaching(final SessionStore<Bytes, byte[]> inner) {
80	        if (!enableCaching) {
81	            return inner;
82	        }
83	        return new CachingSessionStore(inner, storeSupplier.segmentIntervalMs());
84	    }
