86	    private SessionStore<Bytes, byte[]> maybeWrapLogging(final SessionStore<Bytes, byte[]> inner) {
87	        if (!enableLogging) {
88	            return inner;
89	        }
90	        return new ChangeLoggingSessionBytesStoreWithHeaders(inner);
91	    }
