143	                                                                      final Bytes keyTo,
144	                                                                      final long earliestSessionEndTime,
145	                                                                      final long latestSessionStartTime) {
146	            return wrapped().findSessions(keyFrom, keyTo, earliestSessionEndTime, latestSessionStartTime);
147	        }
